'use strict';
const test=require('node:test'),assert=require('node:assert/strict');
const {makeTop10}=require('./radar-top10');
const vehicle={id:'v',name:'Voiture',fuel:'Gazole',consumption:6,tankCapacity:50};
const origin={lat:43.3,lon:5.4};
const stations=Array.from({length:20},(_,i)=>({id:String(i+1),lat:43.3+i*.001,lon:5.4,price:1.5+i*.1}));
function create(opts={}){let calls=0;const routes=opts.routes||(({stations})=>stations.map(s=>({id:s.id,distanceRoundTripKm:2})));const engine=makeTop10({vehicle,fillPercent:80,stations,origin,routeBatch:async args=>{calls++;return routes(args)},...opts});return {engine,get calls(){return calls}};}
test('top 10 garanti parmi 20',async()=>{const x=create();const r=await x.engine.run();assert.equal(r.status,'verified');assert.equal(r.top.length,10);assert.deepEqual(r.top.map(s=>s.id),Array.from({length:10},(_,i)=>String(i+1)));assert.ok(r.skipped.length>0)});
test('ne calcule pas toutes les stations',async()=>{const x=create({batchSize:2});const r=await x.engine.run();assert.ok(r.requests<10);assert.ok(r.skipped.length>=8)});
test('la distance peut changer le top 10',async()=>{const x=create({routes:({stations})=>stations.map(s=>({id:s.id,distanceRoundTripKm:s.id==='1'?1000:2}))});const r=await x.engine.run();assert.equal(r.status,'verified');assert.ok(!r.top.some(s=>s.id==='1'))});
test('route impossible qui peut gagner => non vérifié',async()=>{const x=create({routes:({stations})=>stations.filter(s=>s.id!=='1').map(s=>({id:s.id,distanceRoundTripKm:2}))});const r=await x.engine.run();assert.equal(r.status,'unverified');assert.ok(r.blockers.includes('1'))});
test('route impossible mais trop chère => top vérifié',async()=>{const x=create({batchSize:20,routes:({stations})=>stations.filter(s=>s.id!=='20').map(s=>({id:s.id,distanceRoundTripKm:2}))});const r=await x.engine.run();assert.equal(r.status,'verified')});
test('calcul manuel station hors top',async()=>{const x=create();await x.engine.run();const r=await x.engine.calculateOne('20');assert.equal(r.status,'calculated');assert.ok(r.result.totalCost>0)});
test('calcul manuel réutilise mesure',async()=>{const x=create();await x.engine.run();const before=x.calls;assert.equal((await x.engine.calculateOne('1')).status,'cached');assert.equal(x.calls,before)});
test('calcul manuel station inconnue rejeté',async()=>{const x=create();await assert.rejects(x.engine.calculateOne('bad'),RangeError)});
test('calcul manuel échec réseau',async()=>{const x=create({routes:()=>{throw Error('offline')}});assert.equal((await x.engine.calculateOne('1')).status,'unavailable')});
test('annulation avant routage',async()=>{const ac=new AbortController();ac.abort();const x=create({signal:ac.signal});assert.equal((await x.engine.run()).status,'cancelled');assert.equal(x.calls,0)});
test('annulation pendant routage',async()=>{const ac=new AbortController();const x=create({signal:ac.signal,routes:()=>{ac.abort();return []}});assert.equal((await x.engine.run()).status,'cancelled')});
test('pourcentage invalide',()=>assert.throws(()=>create({fillPercent:0}),RangeError));
test('lot invalide',()=>assert.throws(()=>create({batchSize:0}),RangeError));
test('topK invalide',()=>assert.throws(()=>create({topK:0}),RangeError));
test('origine invalide',()=>assert.throws(()=>create({origin:{lat:100,lon:0}}),TypeError));
test('stations dupliquées',()=>assert.throws(()=>create({stations:[stations[0],stations[0]]})));
test('petit nombre de stations',async()=>{const x=create({stations:stations.slice(0,3)});const r=await x.engine.run();assert.equal(r.status,'verified');assert.equal(r.top.length,3)});
test('égalité de coûts : pas de suppression prématurée',async()=>{const x=create({stations:stations.slice(0,12).map(s=>({...s,price:1.5})),batchSize:2});const r=await x.engine.run();assert.equal(r.status,'verified');assert.equal(r.calculated.length,12)});
test('pas de distance négative',async()=>{const x=create({routes:({stations})=>stations.map(s=>({id:s.id,distanceRoundTripKm:-1}))});const r=await x.engine.run();assert.equal(r.status,'unverified');assert.equal(r.top.length,0)});
test('callback de progression',async()=>{let n=0;const x=create({onProgress:()=>n++});await x.engine.run();assert.ok(n>0)});
test('toutes les stations peuvent être calculées si nécessaire',async()=>{const x=create({stations:stations.slice(0,12).map(s=>({...s,price:1.5})),batchSize:5});const r=await x.engine.run();assert.equal(r.calculated.length,12)});
test('calcul manuel après échec réessaie',async()=>{let fail=true;const x=create({routes:({stations})=>{if(fail)return [];return stations.map(s=>({id:s.id,distanceRoundTripKm:2}))}});await x.engine.run();fail=false;assert.equal((await x.engine.calculateOne('1')).status,'calculated')});
test('prix manquant rejeté',()=>assert.throws(()=>create({stations:[{...stations[0],price:null}]})));
test('top 1 fonctionne',async()=>{const x=create({topK:1,batchSize:1});const r=await x.engine.run();assert.equal(r.status,'verified');assert.equal(r.top.length,1)});
